    "solutionMarkdown": "```python\n\"\"\"\nChapter 15 Capstone Solution: Full-Featured Multi-Command Task & Productivity Manager\n\"\"\"\nimport sys\nimport json\nimport os\nimport datetime\n\nSTORAGE_PATH = \"tasks_db.json\"\n\ndef initialize_database():\n    if not os.path.exists(STORAGE_PATH):\n        with open(STORAGE_PATH, \"w\", encoding=\"utf-8\") as f:\n            json.dump([], f)\n\ndef read_tasks() -> list[dict]:\n    initialize_database()\n    with open(STORAGE_PATH, \"r\", encoding=\"utf-8\") as f:\n        return json.load(f)\n\ndef write_tasks(tasks: list[dict]):\n    with open(STORAGE_PATH, \"w\", encoding=\"utf-8\") as f:\n        json.dump(tasks, f, indent=2)\n\ndef add_task(title: str, priority: str = \"Medium\"):\n    tasks = read_tasks()\n    new_id = (tasks[-1][\"id\"] + 1) if tasks else 1\n    new_entry = {\n        \"id\": new_id,\n        \"title\": title,\n        \"priority\": priority.capitalize(),\n        \"created_at\": datetime.datetime.now().strftime(\"%Y-%m-%d %H:%M\"),\n        \"completed\": False\n    }\n    tasks.append(new_entry)\n    write_tasks(tasks)\n    print(f\"Success: Added Task #{new_id} -> '{title}' [Priority: {priority.capitalize()}]\")\n\ndef list_tasks(show_all: bool = True):\n    tasks = read_tasks()\n    if not tasks:\n        print(\"No tasks found in database.\")\n        return\n    print(f\"\\n{'ID':<4} | {'STATUS':<9} | {'PRIORITY':<8} | {'TITLE':<30} | {'CREATED'}\")\n    print(\"-\" * 75)\n    for t in tasks:\n        if not show_all and t[\"completed\"]:\n            continue\n        status = \"[DONE]\" if t[\"completed\"] else \"[PENDING]\"\n        print(f\"{t['id']:<4} | {status:<9} | {t['priority']:<8} | {t['title']:<30} | {t['created_at']}\")\n\ndef mark_done(task_id: int):\n    tasks = read_tasks()\n    found = False\n    for t in tasks:\n        if t[\"id\"] == task_id:\n            t[\"completed\"] = True\n            found = True\n            break\n    if found:\n        write_tasks(tasks)\n        print(f\"Success: Task #{task_id} marked as completed.\")\n    else:\n        print(f\"Error: Task #{task_id} not found.\")\n\ndef main():\n    if len(sys.argv) < 2:\n        print(\"Usage: python main.py [add <title> [priority]\n\n| list | list-pending | done <id>]\")\n        return\n    action = sys.argv[1].lower()\n    if action == \"add\":\n        if len(sys.argv) < 3:\n            print(\"Error: Task title required.\")\n            return\n        title = sys.argv[2]\n        priority = sys.argv[3] if len(sys.argv) > 3 else \"Medium\"\n        add_task(title, priority)\n    elif action == \"list\":\n        list_tasks(show_all=True)\n    elif action == \"list-pending\":\n        list_tasks(show_all=False)\n    elif action == \"done\":\n        if len(sys.argv) < 3 or not sys.argv[2].isdigit():\n            print(\"Error: Valid integer Task ID required.\")\n            return\n        mark_done(int(sys.argv[2]))\n    else:\n        print(f\"Unknown action '{action}'.\")\n\nif __name__ == \"__main__\":\n    main()\n```\n\n---\n\n# Unit III — The Mathematical Language of CS (Chapters 16–20)",
    "starterCode": "\"\"\"\nChapter 15 Capstone Solution: Full-Featured Multi-Command Task & Productivity Manager\n\"\"\"\nimport sys\nimport json\nimport os\nimport datetime\n\nSTORAGE_PATH = \"tasks_db.json\"\n\ndef initialize_database():\n    if not os.path.exists(STORAGE_PATH):\n        with open(STORAGE_PATH, \"w\", encoding=\"utf-8\") as f:\n            json.dump([], f)\n\ndef read_tasks() -> list[dict]:\n    initialize_database()\n    with open(STORAGE_PATH, \"r\", encoding=\"utf-8\") as f:\n        return json.load(f)\n\ndef write_tasks(tasks: list[dict]):\n    with open(STORAGE_PATH, \"w\", encoding=\"utf-8\") as f:\n        json.dump(tasks, f, indent=2)\n\ndef add_task(title: str, priority: str = \"Medium\"):\n    tasks = read_tasks()\n    new_id = (tasks[-1][\"id\"] + 1) if tasks else 1\n    new_entry = {\n        \"id\": new_id,\n        \"title\": title,\n        \"priority\": priority.capitalize(),\n        \"created_at\": datetime.datetime.now().strftime(\"%Y-%m-%d %H:%M\"),\n        \"completed\": False\n    }\n    tasks.append(new_entry)\n    write_tasks(tasks)\n    print(f\"Success: Added Task #{new_id} -> '{title}' [Priority: {priority.capitalize()}]\")\n\ndef list_tasks(show_all: bool = True):\n    tasks = read_tasks()\n    if not tasks:\n        print(\"No tasks found in database.\")\n        return\n    print(f\"\\n{'ID':<4} | {'STATUS':<9} | {'PRIORITY':<8} | {'TITLE':<30} | {'CREATED'}\")\n    print(\"-\" * 75)\n    for t in tasks:\n        if not show_all and t[\"completed\"]:\n            continue\n        status = \"[DONE]\" if t[\"completed\"] else \"[PENDING]\"\n        print(f\"{t['id']:<4} | {status:<9} | {t['priority']:<8} | {t['title']:<30} | {t['created_at']}\")\n\ndef mark_done(task_id: int):\n    tasks = read_tasks()\n    found = False\n    for t in tasks:\n        if t[\"id\"] == task_id:\n            t[\"completed\"] = True\n            found = True\n            break\n    if found:\n        write_tasks(tasks)\n        print(f\"Success: Task #{task_id} marked as completed.\")\n    else:\n        print(f\"Error: Task #{task_id} not found.\")\n\ndef main():\n    if len(sys.argv) < 2:\n        print(\"Usage: python main.py [add <title> [priority]\n\n| list | list-pending | done <id>]\")\n        return\n    action = sys.argv[1].lower()\n    if action == \"add\":\n        if len(sys.argv) < 3:\n            print(\"Error: Task title required.\")\n            return\n        title = sys.argv[2]\n        priority = sys.argv[3] if len(sys.argv) > 3 else \"Medium\"\n        add_task(title, priority)\n    elif action == \"list\":\n        list_tasks(show_all=True)\n    elif action == \"list-pending\":\n        list_tasks(show_all=False)\n    elif action == \"done\":\n        if len(sys.argv) < 3 or not sys.argv[2].isdigit():\n            print(\"Error: Valid integer Task ID required.\")\n            return\n        mark_done(int(sys.argv[2]))\n    else:\n        print(f\"Unknown action '{action}'.\")\n\nif __name__ == \"__main__\":\n    main()"
