  "28": {
    "chapter": 28,
    "chapterTitle": "Design Patterns",
    "projectTitle": "Document Conversion Suite (Factory, Decorator, Strategy)",
    "format": "Coding (Python)",
    "why": "Implement canonical Gang of Four (GoF) design patterns: Creational, Structural, Behavioral.",
    "problemStatement": "",
    "checklist": [
      "*Factory Method:** Create document parsers (PDF, Markdown, HTML).",
      "*Decorator:** Add compression and encryption wrappers to document output streams.",
      "*Strategy:** Interchange export compression algorithms (Zip vs Gzip)."
    ],
    "workspaceType": "compiler",
    "language": "python",
    "solutionMarkdown": "```python\n# 1. Factory Pattern\nclass DocumentExporterFactory:\n    @staticmethod\n    def create_exporter(format_type: str):\n        if format_type.lower() == \"pdf\": return PDFExporter()\n        elif format_type.lower() == \"csv\": return CSVExporter()\n        raise ValueError(f\"Unknown format: {format_type}\")\n\n# 2. Decorator Pattern\nclass TextStream(ABC):\n    @abstractmethod\n    def write(self, data: str): pass\n\nclass PlainTextStream(TextStream):\n    def write(self, data: str): print(f\"Writing data: {data}\")\n\nclass CompressionDecorator(TextStream):\n    def __init__(self, wrapped: TextStream): self.wrapped = wrapped\n    def write(self, data: str):\n        compressed = f\"[COMPRESSED:{data}]\"\n        self.wrapped.write(compressed)\n\n# 3. Strategy Pattern\nclass CompressionContext:\n    def __init__(self, strategy): self.strategy = strategy\n    def execute(self, payload): return self.strategy.compress(payload)\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 28: DESIGN PATTERNS (FACTORY & OBSERVER) ===\")\n    exporter = DocumentExporterFactory.get_exporter(\"pdf\")\n    exporter.export({\"title\": \"Q3 Financial Report\", \"status\": \"FINAL\"})\n    \n    subject = SystemStateNotifier()\n    subject.attach(AuditLoggerObserver())\n    subject.set_state(\"SYSTEM_READY\")\n```",
    "starterCode": "\"\"\"\nChapter 28 Project Solution: Document Conversion Suite (Factory, Decorator, Strategy)\nFormat: Coding (Python)\n\nProblem:\nDesign Patterns\n\"\"\"\n\n# 1. Factory Pattern\nclass DocumentExporterFactory:\n    @staticmethod\n    def create_exporter(format_type: str):\n        if format_type.lower() == \"pdf\": return PDFExporter()\n        elif format_type.lower() == \"csv\": return CSVExporter()\n        raise ValueError(f\"Unknown format: {format_type}\")\n\n# 2. Decorator Pattern\nclass TextStream(ABC):\n    @abstractmethod\n    def write(self, data: str): pass\n\nclass PlainTextStream(TextStream):\n    def write(self, data: str): print(f\"Writing data: {data}\")\n\nclass CompressionDecorator(TextStream):\n    def __init__(self, wrapped: TextStream): self.wrapped = wrapped\n    def write(self, data: str):\n        compressed = f\"[COMPRESSED:{data}]\"\n        self.wrapped.write(compressed)\n\n# 3. Strategy Pattern\nclass CompressionContext:\n    def __init__(self, strategy): self.strategy = strategy\n    def execute(self, payload): return self.strategy.compress(payload)\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 28: DESIGN PATTERNS (FACTORY & OBSERVER) ===\")\n    exporter = DocumentExporterFactory.get_exporter(\"pdf\")\n    exporter.export({\"title\": \"Q3 Financial Report\", \"status\": \"FINAL\"})\n    \n    subject = SystemStateNotifier()\n    subject.attach(AuditLoggerObserver())\n    subject.set_state(\"SYSTEM_READY\")"
  },
