    "workspaceType": "compiler",
    "language": "python",
    "solutionMarkdown": "```python\nclass DirectChainingHashMap:\n    def __init__(self, initial_capacity: int = 8):\n        self.capacity = initial_capacity\n        self.size = 0\n        self.buckets = [[] for _ in range(self.capacity)]\n\n    def _hash(self, key: str) -> int:\n        hash_val = 0\n        for ch in str(key):\n            hash_val = (hash_val * 31 + ord(ch)) % self.capacity\n        return hash_val\n\n    def put(self, key: str, value):\n        if (self.size / self.capacity) >= 0.75:\n            self._rehash()\n        idx = self._hash(key)\n        for i, (k, v) in enumerate(self.buckets[idx]):\n            if k == key:\n                self.buckets[idx][i] = (key, value)\n                return\n        self.buckets[idx].append((key, value))\n        self.size += 1\n\n    def get(self, key: str):\n        idx = self._hash(key)\n        for k, v in self.buckets[idx]:\n            if k == key: return v\n        raise KeyError(f\"Key '{key}' not found.\")\n\n    def _rehash(self):\n        old_buckets = self.buckets\n        self.capacity *= 2\n        self.buckets = [[] for _ in range(self.capacity)]\n        self.size = 0\n        for bucket in old_buckets:\n            for k, v in bucket:\n                self.put(k, v)\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 36: HASH TABLE WITH SEPARATE CHAINING ===\")\n    ht = DirectChainingHashMap(capacity=4)\n    ht.put(\"apple\", 100)\n    ht.put(\"banana\", 200)\n    ht.put(\"orange\", 300)\n    ht.put(\"grape\", 400)\n    print(\"Get 'banana':\", ht.get(\"banana\"))\n    print(\"Get 'orange':\", ht.get(\"orange\"))\n```",
    "starterCode": "\"\"\"\nChapter 36 Project Solution: Custom HashMap with Separate Chaining & Auto-Resizing\nFormat: Coding (Python from scratch)\n\nProblem:\nHashing\n\"\"\"\n\nclass DirectChainingHashMap:\n    def __init__(self, initial_capacity: int = 8):\n        self.capacity = initial_capacity\n        self.size = 0\n        self.buckets = [[] for _ in range(self.capacity)]\n\n    def _hash(self, key: str) -> int:\n        hash_val = 0\n        for ch in str(key):\n            hash_val = (hash_val * 31 + ord(ch)) % self.capacity\n        return hash_val\n\n    def put(self, key: str, value):\n        if (self.size / self.capacity) >= 0.75:\n            self._rehash()\n        idx = self._hash(key)\n        for i, (k, v) in enumerate(self.buckets[idx]):\n            if k == key:\n                self.buckets[idx][i] = (key, value)\n                return\n        self.buckets[idx].append((key, value))\n        self.size += 1\n\n    def get(self, key: str):\n        idx = self._hash(key)\n        for k, v in self.buckets[idx]:\n            if k == key: return v\n        raise KeyError(f\"Key '{key}' not found.\")\n\n    def _rehash(self):\n        old_buckets = self.buckets\n        self.capacity *= 2\n        self.buckets = [[] for _ in range(self.capacity)]\n        self.size = 0\n        for bucket in old_buckets:\n            for k, v in bucket:\n                self.put(k, v)\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 36: HASH TABLE WITH SEPARATE CHAINING ===\")\n    ht = DirectChainingHashMap(capacity=4)\n    ht.put(\"apple\", 100)\n    ht.put(\"banana\", 200)\n    ht.put(\"orange\", 300)\n    ht.put(\"grape\", 400)\n    print(\"Get 'banana':\", ht.get(\"banana\"))\n    print(\"Get 'orange':\", ht.get(\"orange\"))"
