    "workspaceType": "compiler",
    "language": "python",
    "solutionMarkdown": "```python\ndef search_rotated_sorted_array(nums: list[int], target: int) -> int:\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if nums[mid] == target:\n            return mid\n        # Left half is sorted\n        if nums[left] <= nums[mid]:\n            if nums[left] <= target < nums[mid]:\n                right = mid - 1\n            else:\n                left = mid + 1\n        # Right half is sorted\n        else:\n            if nums[mid] < target <= nums[right]:\n                left = mid + 1\n            else:\n                right = mid - 1\n    return -1\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 40: BINARY SEARCH IN ROTATED ARRAY ===\")\n    arr = [4, 5, 6, 7, 0, 1, 2]\n    target = 0\n    idx = search_rotated_sorted_array(arr, target)\n    print(f\"Array {arr} | Found target {target} at index: {idx}\")\n```",
    "starterCode": "\"\"\"\nChapter 40 Project Solution: Advanced Binary Search Suite (Lower/Upper Bound, Rotated Array)\nFormat: Coding (Python)\n\nProblem:\nSearching\n\"\"\"\n\ndef search_rotated_sorted_array(nums: list[int], target: int) -> int:\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = (left + right) // 2\n        if nums[mid] == target:\n            return mid\n        # Left half is sorted\n        if nums[left] <= nums[mid]:\n            if nums[left] <= target < nums[mid]:\n                right = mid - 1\n            else:\n                left = mid + 1\n        # Right half is sorted\n        else:\n            if nums[mid] < target <= nums[right]:\n                left = mid + 1\n            else:\n                right = mid - 1\n    return -1\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 40: BINARY SEARCH IN ROTATED ARRAY ===\")\n    arr = [4, 5, 6, 7, 0, 1, 2]\n    target = 0\n    idx = search_rotated_sorted_array(arr, target)\n    print(f\"Array {arr} | Found target {target} at index: {idx}\")"
