    "solutionMarkdown": "```python\ndef min_window_substring(s: str, t: str) -> str:\n    if not t or not s: return \"\"\n    target_counts = {}\n    for c in t: target_counts[c] = target_counts.get(c, 0) + 1\n  \n    window_counts = {}\n    have, need = 0, len(target_counts)\n    res, res_len = [-1, -1], float('inf')\n    left = 0\n  \n    for right, c in enumerate(s):\n        window_counts[c] = window_counts.get(c, 0) + 1\n        if c in target_counts and window_counts[c] == target_counts[c]:\n            have += 1\n          \n        while have == need:\n            if (right - left + 1) < res_len:\n                res = [left, right]\n                res_len = right - left + 1\n            window_counts[s[left]] -= 1\n            if s[left] in target_counts and window_counts[s[left]] < target_counts[s[left]]:\n                have -= 1\n            left += 1\n          \n    l, r = res\n    return s[l:r+1] if res_len != float('inf') else \"\"\nif __name__ == \"__main__\":\n    print(\"=== CHAPTER 42: SLIDING WINDOW (MIN WINDOW SUBSTRING) ===\")\n    s, t = \"ADOBECODEBANC\", \"ABC\"\n    res = min_window_substring(s, t)\n    print(f\"Min window in '{s}' containing '{t}': '{res}'\")\n```",
